	Tracing        TracingConfig        `json:"tracing,omitempty" mapstructure:"tracing" yaml:"tracing,omitempty"`
	UI             UIConfig             `json:"ui,omitempty" mapstructure:"ui" yaml:"ui,omitempty"`
}

type Result struct {
	Config   *Config
	Warnings []string
}

// Dir returns the default root directory for Flipt configuration
func Dir() (string, error) {
	configDir, err := os.UserConfigDir()
	if err != nil {
		return "", fmt.Errorf("getting user config dir: %w", err)
	}

	return filepath.Join(configDir, "flipt"), nil
}

func Load(path string) (*Result, error) {
	v := viper.New()
	v.SetEnvPrefix("FLIPT")
	v.SetEnvKeyReplacer(strings.NewReplacer(".", "_"))
	v.AutomaticEnv()

	var cfg *Config

	if path == "" {
		cfg = Default()
	} else {
		cfg = &Config{}
		v.SetConfigFile(path)
		if err := v.ReadInConfig(); err != nil {
			return nil, fmt.Errorf("loading configuration: %w", err)
		return err
	}

	fmt.Println(bundle.Digest)

	return nil
}

func (c *bundleCommand) getStore() (*oci.Store, error) {
	logger, cfg, err := buildConfig()
	if err != nil {
		return nil, err
	}

	var opts []containers.Option[oci.StoreOptions]
	if cfg := cfg.Storage.OCI; cfg != nil {
		if cfg.BundleDirectory != "" {
			opts = append(opts, oci.WithBundleDir(cfg.BundleDirectory))
		}

		if cfg.Authentication != nil {
			opts = append(opts, oci.WithCredentials(
				cfg.Authentication.Username,
				cfg.Authentication.Password,
			))
		}
	}

	return oci.NewStore(logger, opts...)
}

func writer() *tabwriter.Writer {
	return tabwriter.NewWriter(os.Stdout, 0, 0, 3, ' ', 0)
}

